def finding(item, n, refs):
    fid, name, primary, required = item
    low = name.lower()
    kinds = [primary, KINDS[(n + 6) % len(KINDS)], KINDS[(n + 15) % len(KINDS)]]
    return {"id": fid, "name": name,
      "description": f"Records {low} as source-qualified catalog context while dataset, service, distribution, policy, agreement, subscription, order, delivery, usage, issue, audit and records masters remain external.",
      "source_refs": refs,
      "questions": [
       {"id": f"{fid}-q01", "text": f"What stable identity, version, typed value, scope and explicit unknown establish {low}?", "kind": kinds[0], "answer_data": ["record, offering and external master identifiers", "typed value, vocabulary, schema or profile version", "unknown, unavailable, disputed and not-applicable states"]},
       {"id": f"{fid}-q02", "text": f"Who created, owns, asserts, reviews, approves, supplies, consumes or may rely on {low}, for which purpose and under what authority?", "kind": kinds[1], "answer_data": ["actor, agent, role, organization and contact", "purpose, audience, authority, policy and access", "conflict, exception, escalation and accountability"]},
       {"id": f"{fid}-q03", "text": f"Which event, effective, publication, modification, recorded, ingestion and knowledge times, evidence and uncertainty qualify {low}?", "kind": kinds[2], "answer_data": ["distinct product, record, resource and knowledge times", "source, evidence, confidence, uncertainty and limitation", "successor, correction, retention and audit"]}],
      "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed catalog data for {low}, qualified by offering, source, purpose, authority, time, uncertainty and provenance.", "value_kind": "collection", "cardinality": "1" if required else "0..n", "required": required, "source_refs": refs}],
      "artifacts": [{"id": f"{fid}-record", "name": f"{name} record", "description": f"Immutable or successor-versioned catalog evidence for {low}.", "media_or_form": ["logical catalog assertion", "description, binding, policy reference, observation, feedback, correction or projection record"], "serial": True, "identity_strategy": f"Catalog record ID plus independent offering, resource, policy or artifact ID for {fid}; title, URL, date, digest and endpoint never identify the offering alone.", "source_refs": refs}],
      "inline_only_rationale": None}

def structure():
    bundles, n = [], 0
    for bid, bname, rationale, layers in ROWS:
        rendered = []
        for lid, lname, refs, items in layers:
            fs = []
            for item in items:
                n += 1
                fs.append(finding(item, n, refs))
            rendered.append({"id": lid, "name": lname, "description": f"Groups source-qualified catalog context for {lname.lower()}.", "source_refs": refs, "findings": fs})
        bundles.append({"id": bid, "name": bname, "description": f"Groups governed catalog context for {bname.lower()}.", "rationale": rationale + ".", "source_refs": sorted({r for layer in layers for r in layer[2]}), "layers": rendered})
    return {"bundles": bundles}

